### 3.5 Suporte completo a séries

**O quê:** séries passam a ser cidadãs do app, como os filmes:

- opção "Série" no wizard (pergunta 1);
- página de detalhes da série (`/serie/[id]`): sinopse, temporadas, duração média do episódio, elenco, onde assistir, trailer;
- reações e listas aceitam séries;
- o "Como foi?" funciona para séries também.

**Por quê:** à noite, muita gente quer "um episódio de alguma coisa", não um filme de 2 horas.

**Atenção, risco técnico:** no TMDB, filme e série têm sequências de ID independentes, então o mesmo número pode ser um filme e uma série diferentes. Hoje `reacoes` e `lista_itens` usam a chave `(usuario_id, tmdb_id)`. Será preciso:

- adicionar uma coluna `tipo` (`filme` | `serie`) com padrão `filme`, para que todos os dados atuais continuem válidos;
- trocar a chave para `(usuario_id, tipo, tmdb_id)`;
- fazer isso numa **migration nova**, sem apagar nem recriar as tabelas (o banco de produção tem dados reais);
- revisar tudo o que lê essas tabelas: motor, dashboard, "Me surpreenda", listas, MCP. Onde só se espera filme, filtrar `tipo = 'filme'`.

Os gêneros de série no TMDB também são outra lista (`/genre/tv/list`), com IDs diferentes dos de filme.

**Fora do escopo agora:** seções de série no dashboard, séries no motor de recomendação, no "Me surpreenda", na busca e no MCP.

### 3.6 "Noite a dois" (para depois)

**O quê:** uma pessoa abre o wizard, toca em "Vamos escolher juntos" e manda um link. Cada um responde as perguntas no próprio celular, e o app sugere algo que agrade aos dois, com um motivo do tipo "ela quer rir, você quer tensão: comédia de ação".

**Por quê:** o maior conflito da noite não é "o que eu vejo", é "o que a gente vê".

Não cabe nos 4 dias. Fica registrada para quem continuar.
// @vitest-environment node
import { NextRequest, NextResponse } from "next/server";
import { describe, expect, it, vi } from "vitest";

import { updateSession } from "@/lib/supabase/middleware";
import { proxy } from "@/proxy";

vi.mock("@/lib/supabase/middleware", () => ({ updateSession: vi.fn() }));

function sessao(user: { id: string } | null) {
  vi.mocked(updateSession).mockResolvedValue({ response: NextResponse.next(), user } as never);
}

describe("proxy", () => {
  it("sem sessão, manda /noite para o login guardando as respostas em next", async () => {
    sessao(null);

    const resposta = await proxy(new NextRequest("http://localhost/noite?humor=cansado"));

    const destino = new URL(resposta.headers.get("location")!);
    expect(destino.pathname).toBe("/login");
    expect(destino.searchParams.get("next")).toBe("/noite?humor=cansado");
  });

  it("com sessão, deixa /noite passar", async () => {
    sessao({ id: "u-1" });

    const resposta = await proxy(new NextRequest("http://localhost/noite"));

    expect(resposta.headers.get("location")).toBeNull();
  });
});

import type { Clima, Pergunta } from "@/features/metricas/eventos";
import type { MotivoTroca } from "@/features/noite/estado";

export type Humor = Clima["humor"];
export type Experiencia = Clima["experiencia"];
export type Companhia = Clima["companhia"];

/**
 * As telas do wizard, na ordem, com o parâmetro de cada resposta na URL.
 * Os rótulos das respostas estão em `ROTULOS_CLIMA` (`src/features/metricas/rotulos.ts`).
 */
export const PERGUNTAS = [
  { chave: "humor", parametro: "humor", titulo: "Como você está se sentindo?" },
  { chave: "experiencia", parametro: "exp", titulo: "Que tipo de experiência você quer?" },
  { chave: "companhia", parametro: "com", titulo: "Com quem vai assistir?" },
] as const satisfies { chave: Pergunta; parametro: string; titulo: string }[];

/** Horários do "Até que horas?" (SPEC/2026-11-18-noite-ate-que-horas.md): meia-noite é 0. */
export const HORAS_LIMITE = [22, 23, 0, 1] as const;
export type HoraLimite = (typeof HORAS_LIMITE)[number];

/** Rótulo de cada botão do "Até que horas?". */
export const ROTULOS_HORA: Record<HoraLimite, string> = {
  22: "22h",
  23: "23h",
  0: "Meia-noite",
  1: "1h",
};

/** "Não dá tempo de ver um filme até as 23h". */
export const ATE_A_HORA: Record<HoraLimite, string> = {
  22: "até as 22h",
  23: "até as 23h",
  0: "até a meia-noite",
  1: "até a 1h",
};

/** Motivos de "Esse não", na ordem do pedido do cliente (3.2). */
export const ROTULOS_MOTIVO: Record<MotivoTroca, string> = {
  "ja-vi": "Já vi",
  "nao-e-o-clima": "Não é o clima",
  "muito-longo": "Muito longo",
  outro: "Outro",
};

/** Trechos do motivo: "Você está cansado, quer rir e vai ver a dois". */
export const TRECHOS: { [P in Pergunta]: Record<Clima[P], string> } = {
  humor: {
    cansado: "Você está cansado",
    animado: "Você está animado",
    "pra-baixo": "Você está pra baixo",
    nostalgico: "Você está nostálgico",
    ansioso: "Você está ansioso",
    "de-boa": "Você está de boa",
  },
  experiencia: {
    rir: "quer rir",
    emocionar: "quer se emocionar",
    susto: "quer levar um susto",
    tenso: "quer ficar tenso",
    pensar: "quer pensar",
    distrair: "quer só se distrair",
  },
  companhia: {
    sozinho: "vai ver sozinho",
    "a-dois": "vai ver a dois",
    familia: "vai ver com as crianças",
    amigos: "vai ver com os amigos",
  },
};
import type { Companhia, Experiencia, Humor } from "@/features/noite/opcoes";
import type { ClassificacaoBR, OrdemDescoberta } from "@/lib/tmdb/tipos";

/**
 * Tabelas de mapeamento das respostas para os filtros do TMDB.
 * Espelham as tabelas de `SPEC/2026-11-18-wizard-noite.md`, que o cliente revisa.
 */

/** IDs de gênero de filme do TMDB usados no wizard. */
const G = {
  acao: 28,
  animacao: 16,
  aventura: 12,
  comedia: 35,
  crime: 80,
  drama: 18,
  ficcao: 878,
  guerra: 10752,
  historia: 36,
  misterio: 9648,
  romance: 10749,
  terror: 27,
  thriller: 53,
} as const;

/** Um "tom" da experiência: os gêneros exigidos juntos e o nome que vai no motivo. */
export type Tom = { nome: string; generos: number[] };

/** Tons de cada experiência, em ordem ("Não é o clima" passa ao seguinte), e exclusões fixas. */
export const TONS: Record<Experiencia, { tons: Tom[]; sem?: number[] }> = {
  rir: {
    tons: [
      { nome: "comédia leve", generos: [G.comedia] },
      { nome: "comédia romântica", generos: [G.comedia, G.romance] },
      { nome: "comédia de aventura", generos: [G.comedia, G.aventura] },
    ],
    sem: [G.terror, G.thriller, G.crime, G.guerra],
  },
  emocionar: {
    tons: [
      { nome: "drama", generos: [G.drama] },
      { nome: "romance", generos: [G.romance, G.drama] },
      { nome: "drama de época", generos: [G.drama, G.historia] },
    ],
  },
  susto: {
    tons: [
      { nome: "terror", generos: [G.terror] },
      { nome: "terror de mistério", generos: [G.terror, G.misterio] },
      { nome: "terror de ficção científica", generos: [G.terror, G.ficcao] },
    ],
  },
  tenso: {
    tons: [
      { nome: "suspense", generos: [G.thriller] },
      { nome: "policial", generos: [G.crime, G.thriller] },
      { nome: "mistério", generos: [G.misterio] },
    ],
  },
  pensar: {
    tons: [
      { nome: "ficção científica", generos: [G.ficcao] },
      { nome: "mistério", generos: [G.misterio, G.drama] },
      { nome: "drama para refletir", generos: [G.drama] },
    ],
  },
  distrair: {
    tons: [
      { nome: "aventura", generos: [G.aventura] },
      { nome: "ação", generos: [G.acao] },
      { nome: "animação", generos: [G.animacao] },
    ],
    sem: [G.terror, G.guerra],
  },
};

/** Quantos tons cada experiência tem (o `tom` da URL vai de 0 a TOTAL_TONS - 1). */
export const TOTAL_TONS = 3;

type AjusteHumor = {
  duracaoMax?: number;
  ordem?: OrdemDescoberta;
  lancadoAte?: string;
  /** Excluídos, salvo se o tom atual pedir o gênero. */
  sem?: number[];
};

const PESADOS = [G.terror, G.thriller, G.guerra];

export const AJUSTES_HUMOR: Record<Humor, AjusteHumor> = {
  cansado: { duracaoMax: 110, ordem: "popularidade" },
  animado: {},
  "pra-baixo": { sem: PESADOS },
  nostalgico: { lancadoAte: "2005-12-31" },
  ansioso: { sem: PESADOS },
  "de-boa": {},
};

/** Classificação máxima em "família com crianças" (proposta da issue #2). */
export const CLASSIFICACAO_FAMILIA: ClassificacaoBR = "12";

export const AJUSTES_COMPANHIA: Record<
  Companhia,
  { classificacaoMax?: ClassificacaoBR; ordem?: OrdemDescoberta }
> = {
  sozinho: {},
  "a-dois": {},
  familia: { classificacaoMax: CLASSIFICACAO_FAMILIA },
  amigos: { ordem: "popularidade" },
};

/** Piso de qualidade, sempre aplicado. */
export const PISO = { notaMin: 6.5, votosMin: 300 } as const;

export const ORDEM_PADRAO: OrdemDescoberta = "nota";

/** "Muito longo": quanto encurtar, o mínimo e a base quando a duração é desconhecida. */
export const DURACAO_TROCA = { reducao: 20, minima: 80, base: 120 } as const;

/** "Até que horas?": com menos minutos que isso, não há filme a sugerir. */
export const TEMPO_MINIMO = 60;
import type { Clima } from "@/features/metricas/eventos";
import {
  AJUSTES_COMPANHIA,
  AJUSTES_HUMOR,
  ORDEM_PADRAO,
  PISO,
  TONS,
  type Tom,
} from "@/features/noite/mapeamento";
import type { FiltrosDescoberta } from "@/lib/tmdb/tipos";

export type RodadaNoite = {
  respostas: Clima;
  /** Índice do tom ("Não é o clima" avança). */
  tom: number;
  /** Limite de duração vindo de "Muito longo", se houver. */
  duracaoMax: number | null;
  /** Minutos até a hora do "Até que horas?", se houver. */
  tempo?: number | null;
};

export type FiltrosNoite = { filtros: FiltrosDescoberta; tom: Tom };

/**
 * Filtros do TMDB para a rodada (tabelas de `SPEC/2026-11-18-wizard-noite.md`).
 * A experiência escolhe o tom; o humor e a companhia ajustam; os gêneros evitados do perfil
 * são absolutos, e os favoritos não entram. `null` se todos os tons tiverem gênero evitado.
 */
export function filtrosDaNoite(rodada: RodadaNoite, evitados: number[]): FiltrosNoite | null {
  const { respostas, tom, duracaoMax, tempo } = rodada;
  const experiencia = TONS[respostas.experiencia];
  const disponiveis = experiencia.tons.filter((t) => !t.generos.some((g) => evitados.includes(g)));
  const escolhido = disponiveis[tom % disponiveis.length];
  if (!escolhido) return null;

  const humor = AJUSTES_HUMOR[respostas.humor];
  const companhia = AJUSTES_COMPANHIA[respostas.companhia];
  // A experiência manda mais que o humor: o humor não exclui o gênero do tom.
  const semDoHumor = (humor.sem ?? []).filter((g) => !escolhido.generos.includes(g));
  const semGeneros = [...new Set([...evitados, ...(experiencia.sem ?? []), ...semDoHumor])];
  // "Cansado", "Muito longo" e "Até que horas?": vale o menor limite.
  const limites = [humor.duracaoMax, duracaoMax, tempo].filter((n) => typeof n === "number");

  return {
    tom: escolhido,
    filtros: {
      todosGeneros: escolhido.generos,
      ...(semGeneros.length > 0 && { semGeneros }),
      ...(limites.length > 0 && { duracaoMax: Math.min(...limites) }),
      ...(humor.lancadoAte && { lancadoAte: humor.lancadoAte }),
      ...(companhia.classificacaoMax && { classificacaoMax: companhia.classificacaoMax }),
      notaMin: PISO.notaMin,
      votosMin: PISO.votosMin,
      ordem: humor.ordem ?? companhia.ordem ?? ORDEM_PADRAO,
    },
  };
}

import {
  CLIMAS,
  climaSchema,
  MAX_TROCAS,
  type Clima,
  MOTIVOS_TROCA,
  type Pergunta,
} from "@/features/metricas/eventos";
import { DURACAO_TROCA, TOTAL_TONS } from "@/features/noite/mapeamento";
import { HORAS_LIMITE, PERGUNTAS, type HoraLimite } from "@/features/noite/opcoes";
import { minutosAte } from "@/features/noite/termina";
import { limparIds } from "@/features/surpresa/memoria";

export type MotivoTroca = (typeof MOTIVOS_TROCA)[number];

/** Tudo o que o wizard sabe, guardado só na URL de `/noite`. */
export type EstadoNoite = {
  respostas: Partial<Clima>;
  tom: number;
  /** Limite de duração vindo de "Muito longo". */
  duracaoMax: number | null;
  /** IDs já mostrados nesta sessão do wizard. */
  vistos: number[];
  trocas: number;
  /** "Até que horas?": a hora escolhida, ou `null` para "Tanto faz". Sempre junto de `tempo`. */
  ate: HoraLimite | null;
  /** Minutos que faltavam até `ate`, calculados no navegador da pessoa. */
  tempo: number | null;
};

export const ROTA_NOITE = "/noite";
export const MAX_VISTOS_NOITE = 50;
const DURACAO_MAXIMA_URL = 600;
const TEMPO_MAXIMO_URL = 24 * 60;

export const ESTADO_INICIAL: EstadoNoite = {
  respostas: {},
  tom: 0,
  duracaoMax: null,
  vistos: [],
  trocas: 0,
  ate: null,
  tempo: null,
};

type Busca = Record<string, string | string[] | undefined>;

function texto(valor: string | string[] | undefined): string | undefined {
  return typeof valor === "string" ? valor : undefined;
}

function inteiro(valor: string | string[] | undefined, min: number, max: number): number | null {
  const bruto = texto(valor);
  if (!bruto || !/^\d{1,4}$/.test(bruto)) return null;
  const numero = Number(bruto);
  return numero >= min && numero <= max ? numero : null;
}

function resposta<P extends Pergunta>(pergunta: P, valor: string | undefined) {
  return (CLIMAS[pergunta] as readonly string[]).includes(valor ?? "")
    ? (valor as Clima[P])
    : undefined;
}

/** Lê o estado dos `searchParams` de `/noite`; valores inválidos são ignorados. */
export function lerEstado(busca: Busca): EstadoNoite {
  const respostas: Partial<Clima> = {};
  for (const { chave, parametro } of PERGUNTAS) {
    const valor = resposta(chave, texto(busca[parametro]));
    if (valor) Object.assign(respostas, { [chave]: valor });
  }
  const vistos = (texto(busca.vistos) ?? "").split(",").filter(Boolean).map(Number);
  const hora = inteiro(busca.ate, 0, 23);
  const ate = HORAS_LIMITE.find((h) => h === hora) ?? null;
  const tempo = inteiro(busca.tempo, 0, TEMPO_MAXIMO_URL);
  // A hora e os minutos só valem juntos: sem um deles, é "Tanto faz".
  const horario = ate !== null && tempo !== null ? { ate, tempo } : { ate: null, tempo: null };

  return {
    respostas,
    tom: inteiro(busca.tom, 0, TOTAL_TONS - 1) ?? 0,
    duracaoMax: inteiro(busca.max, DURACAO_TROCA.minima, DURACAO_MAXIMA_URL),
    vistos: limparIds(vistos).slice(-MAX_VISTOS_NOITE),
    trocas: inteiro(busca.trocas, 0, MAX_TROCAS) ?? 0,
    ...horario,
  };
}

/** A próxima pergunta sem resposta, na ordem das telas, ou `null` com as três respondidas. */
export function proximaPergunta(estado: EstadoNoite): (typeof PERGUNTAS)[number] | null {
  return PERGUNTAS.find(({ chave }) => !estado.respostas[chave]) ?? null;
}

/** As três respostas, quando completas e válidas. */
export function respostasCompletas(estado: EstadoNoite): Clima | null {
  const resultado = climaSchema.safeParse(estado.respostas);
  return resultado.success ? resultado.data : null;
}

/** URL de `/noite` para o estado, só com os parâmetros que fogem do padrão. */
export function urlDaNoite(estado: EstadoNoite): string {
  const busca = new URLSearchParams();
  for (const { chave, parametro } of PERGUNTAS) {
    const valor = estado.respostas[chave];
    if (valor) busca.set(parametro, valor);
  }
  if (estado.ate !== null && estado.tempo !== null) {
    busca.set("ate", String(estado.ate));
    busca.set("tempo", String(estado.tempo));
  }
  if (estado.tom > 0) busca.set("tom", String(estado.tom));
  if (estado.duracaoMax !== null) busca.set("max", String(estado.duracaoMax));
  if (estado.vistos.length > 0) busca.set("vistos", estado.vistos.join(","));
  if (estado.trocas > 0) busca.set("trocas", String(estado.trocas));
  const consulta = busca.toString().replaceAll("%2C", ",");
  return consulta ? `${ROTA_NOITE}?${consulta}` : ROTA_NOITE;
}

/** URL com mais uma resposta: o cartão de cada opção do wizard é um link para ela. */
export function urlComResposta<P extends Pergunta>(
  estado: EstadoNoite,
  pergunta: P,
  valor: Clima[P],
): string {
  return urlDaNoite({ ...estado, respostas: { ...estado.respostas, [pergunta]: valor } });
}

/**
 * "Até que horas?": o mesmo estado com a hora escolhida e os minutos que faltam no relógio
 * `agora` (o do navegador). `null` é "Tanto faz". Não é troca: o resto do estado fica igual.
 */
export function comHorario(estado: EstadoNoite, hora: HoraLimite | null, agora: Date): EstadoNoite {
  if (hora === null) return { ...estado, ate: null, tempo: null };
  return { ...estado, ate: hora, tempo: minutosAte(hora, agora) };
}

/** Encurta o limite de duração depois de "Muito longo" (tabela de precedência da spec). */
function encurtar(atual: number | null, duracaoRecusada: number | null): number {
  const { reducao, minima, base } = DURACAO_TROCA;
  const novo = (duracaoRecusada ?? atual ?? base) - reducao;
  return Math.max(minima, Math.min(novo, atual ?? novo));
}

/**
 * Estado da próxima rodada depois de "Esse não": os filmes mostrados entram em `vistos`,
 * o motivo ajusta o tom ou a duração e `trocas` sobe. `null` quando já não há trocas.
 * `mostrados[0]` é o destaque recusado.
 */
export function proximaRodada(
  estado: EstadoNoite,
  motivo: MotivoTroca,
  mostrados: { id: number; duracaoMin: number | null }[],
): EstadoNoite | null {
  if (estado.trocas >= MAX_TROCAS) return null;
  const vistos = limparIds([...estado.vistos, ...mostrados.map(({ id }) => id)]);

  return {
    ...estado,
    vistos: vistos.slice(-MAX_VISTOS_NOITE),
    trocas: estado.trocas + 1,
    tom: motivo === "nao-e-o-clima" ? (estado.tom + 1) % TOTAL_TONS : estado.tom,
    duracaoMax:
      motivo === "muito-longo"
        ? encurtar(estado.duracaoMax, mostrados[0]?.duracaoMin ?? null)
        : estado.duracaoMax,
  };
}

/** URL da próxima rodada para cada motivo de "Esse não", ou `null` sem trocas restantes. */
export function urlsDaTroca(
  estado: EstadoNoite,
  mostrados: { id: number; duracaoMin: number | null }[],
): Record<MotivoTroca, string> | null {
  const urls = {} as Record<MotivoTroca, string>;
  for (const motivo of MOTIVOS_TROCA) {
    const proxima = proximaRodada(estado, motivo, mostrados);
    if (!proxima) return null;
    urls[motivo] = urlDaNoite(proxima);
  }
  return urls;
}
import type { Clima } from "@/features/metricas/eventos";
import type { EstadoNoite } from "@/features/noite/estado";
import { filtrosDaNoite } from "@/features/noite/filtros";
import { motivoDaNoite, provedorDaNoite } from "@/features/noite/motivo";
import type { PreferenciasInput } from "@/features/preferencias/schema";
import type { ApiFilmes } from "@/lib/tmdb/filmes";
import type {
  FilmeDetalhes,
  FilmeResumo,
  FiltrosDescoberta,
  Pagina,
  Provedor,
} from "@/lib/tmdb/tipos";

export type ApiNoite = Pick<ApiFilmes, "descobrirFilmes" | "obterFilme">;
export type PerfilNoite = Pick<PreferenciasInput, "generosEvitados" | "streamings">;

export type FilmeDaNoite = { filme: FilmeDetalhes; provedor: Provedor | null; motivo: string };
export type ResultadoNoite = { destaque: FilmeDaNoite; opcoes: FilmeDaNoite[] };

type Entrada = {
  respostas: Clima;
  estado: Pick<EstadoNoite, "tom" | "duracaoMax" | "vistos" | "trocas"> &
    Partial<Pick<EstadoNoite, "tempo">>;
  perfil: PerfilNoite;
  /** "Já assisti" e filmes com reação. */
  excluir: number[];
  api: ApiNoite;
};

/** Páginas lidas por consulta para completar a rodada. */
const PAGINAS_POR_CONSULTA = 2;

/** O TMDB falhou e a rodada ficou sem filmes: refazer as perguntas não resolveria. */
export class NoiteIndisponivel extends Error {
  constructor() {
    super("O TMDB falhou e a rodada ficou sem filmes.");
    this.name = "NoiteIndisponivel";
  }
}

async function consultar(
  api: ApiNoite,
  filtros: FiltrosDescoberta,
  aoFalhar: () => void,
): Promise<Pagina<FilmeResumo>> {
  try {
    return await api.descobrirFilmes(filtros);
  } catch (erro) {
    console.error("[noite] consulta falhou:", erro);
    aoFalhar();
    return { itens: [], pagina: 1, totalPaginas: 0, totalResultados: 0 };
  }
}

async function detalhar(
  api: ApiNoite,
  id: number,
  aoFalhar: () => void,
): Promise<FilmeDetalhes | null> {
  try {
    return await api.obterFilme(id);
  } catch (erro) {
    console.error("[noite] detalhes falharam:", erro);
    aoFalhar();
    return null;
  }
}

/**
 * Filmes da rodada: 1 na primeira, 1 destaque + 2 opções depois de uma troca.
 * Busca primeiro nos streamings da pessoa e completa sem filtro de provedor. Nunca devolve
 * filme excluído, já mostrado, de gênero evitado ou que passa do "Até que horas?". `null` quando não sobra nenhum; lança
 * `NoiteIndisponivel` quando não sobra nenhum porque o TMDB falhou.
 */
export async function recomendarNoite({
  respostas,
  estado,
  perfil,
  excluir,
  api,
}: Entrada): Promise<ResultadoNoite | null> {
  const evitados = perfil.generosEvitados;
  const { tom, duracaoMax, tempo = null } = estado;
  const noite = filtrosDaNoite({ respostas, tom, duracaoMax, tempo }, evitados);
  if (!noite) return null;

  let falhou = false;
  const aoFalhar = () => {
    falhou = true;
  };
  const quantidade = estado.trocas === 0 ? 1 : 3;
  const bloqueados = new Set([...excluir, ...estado.vistos]);
  const escolhidos: FilmeResumo[] = [];
  const consultas: FiltrosDescoberta[] = perfil.streamings.length
    ? [{ ...noite.filtros, provedores: perfil.streamings }, noite.filtros]
    : [noite.filtros];

  for (const filtros of consultas) {
    for (let pagina = 1; pagina <= PAGINAS_POR_CONSULTA; pagina++) {
      if (escolhidos.length >= quantidade) break;
      const resultado = await consultar(api, { ...filtros, pagina }, aoFalhar);
      for (const filme of resultado.itens) {
        const evitado = filme.generos.some((genero) => evitados.includes(genero));
        if (escolhidos.length >= quantidade || evitado || bloqueados.has(filme.id)) continue;
        escolhidos.push(filme);
        bloqueados.add(filme.id);
      }
      if (pagina >= resultado.totalPaginas) break;
    }
  }

  // "Até que horas?" promete que o filme termina a tempo: confere a duração nos detalhes.
  const cabe = ({ duracaoMin }: FilmeDetalhes) =>
    tempo === null || (duracaoMin !== null && duracaoMin <= tempo);
  const detalhes = await Promise.all(escolhidos.map(({ id }) => detalhar(api, id, aoFalhar)));
  const [destaque, ...opcoes] = detalhes
    .filter((filme): filme is FilmeDetalhes => filme !== null && cabe(filme))
    .map((filme) => {
      const provedor = provedorDaNoite(filme.ondeAssistir, perfil.streamings);
      return { filme, provedor, motivo: motivoDaNoite(respostas, noite.tom, filme, provedor) };
    });
  if (destaque) return { destaque, opcoes };
  if (falhou) throw new NoiteIndisponivel();
  return null;
}

