import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState, useTransition } from "react";

import { Button, buttonVariants } from "@/components/ui/button";
import { alternarLista } from "@/features/listas/actions";
import { enviarEvento } from "@/features/metricas/enviar";
import { MOTIVOS_TROCA } from "@/features/metricas/eventos";
import { ROTA_NOITE, type MotivoTroca } from "@/features/noite/estado";
import { ROTULOS_MOTIVO } from "@/features/noite/opcoes";

type Props = {
  /** URL da próxima rodada por motivo (calculada no servidor), ou `null` no limite de trocas. */
  proximas: Record<MotivoTroca, string> | null;
  trocasRestantes: number;
  /** O destaque da rodada, que "Já vi" pode marcar como "Já assisti". */
  destaque: { id: number; titulo: string };
};

/**
 * "Esse não": pede o porquê, registra `wizard_troca` e vai para a próxima rodada.
 * "Já vi" oferece marcar o destaque como "Já assisti". No limite, oferece refazer as perguntas.
 */
export function EsseNao({ proximas, trocasRestantes, destaque }: Props) {
  const router = useRouter();
  const [etapa, setEtapa] = useState<"botao" | "motivos" | "ja-vi">("botao");
  const [erro, setErro] = useState<string>();
  const [trocando, iniciar] = useTransition();

  if (!proximas) {
    return (
      <div className="flex flex-col items-start gap-2">
        <p className="text-muted-foreground text-sm">Você chegou ao limite de trocas.</p>
        <Link href={ROTA_NOITE} className={buttonVariants({ variant: "outline", size: "lg" })}>
          Refazer as perguntas
        </Link>
      </div>
    );
  }

  const trocar = (url: string) => iniciar(() => router.push(url));

  const escolher = (motivo: MotivoTroca) => {
    enviarEvento({ nome: "wizard_troca", dados: { motivo } });
    if (motivo === "ja-vi") setEtapa("ja-vi");
    else trocar(proximas[motivo]);
  };

  const marcarETrocar = () =>
    iniciar(async () => {
      const dados = new FormData();
      dados.set("tmdbId", String(destaque.id));
      dados.set("status", "assistido");
      const { mensagem } = await alternarLista({}, dados);
      if (mensagem) setErro(mensagem);
      else router.push(proximas["ja-vi"]);
    });

  return (
    <div className="flex flex-col gap-3">
      {etapa === "botao" && (
        <div className="flex flex-wrap items-center gap-3">
          <Button
            variant="outline"
            className="h-12 px-6 text-base"
            onClick={() => setEtapa("motivos")}
          >
            Esse não
          </Button>
          <p className="text-muted-foreground text-sm">Trocas restantes: {trocasRestantes}</p>
        </div>
      )}
      {etapa === "motivos" && (
        <div role="group" aria-label="Por que não?" className="grid grid-cols-2 gap-2 sm:flex">
          {MOTIVOS_TROCA.map((motivo) => (
            <Button
              key={motivo}
              variant="outline"
              className="h-12 text-base"
              disabled={trocando}
              onClick={() => escolher(motivo)}
            >
              {ROTULOS_MOTIVO[motivo]}
            </Button>
          ))}
        </div>
      )}
      {etapa === "ja-vi" && (
        <div className="flex flex-col gap-3">
          <p>
            Quer marcar <strong>{destaque.titulo}</strong> como “Já assisti”? Assim ele sai também
            das suas recomendações.
          </p>
          <div className="flex flex-wrap gap-2">
            <Button className="h-12 text-base" disabled={trocando} onClick={marcarETrocar}>
              Marcar e trocar
            </Button>
            <Button
              variant="outline"
              className="h-12 text-base"
              disabled={trocando}
              onClick={() => trocar(proximas["ja-vi"])}
            >
              Só trocar
            </Button>
          </div>
        </div>
      )}
      {erro && (
        <p role="alert" className="text-destructive text-sm">
          {erro}
        </p>
      )}
    </div>
  );
}

"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";

import { contarExibicao, gravarEscolha, gravarResposta } from "@/features/como-foi/gravar";
import { RESPOSTAS_COMO_FOI } from "@/features/metricas/eventos";
import { tmdbIdSchema } from "@/features/reacoes/schema";
import { createClient } from "@/lib/supabase/server";

export type EstadoComoFoi = { mensagem?: string };

const SESSAO_EXPIRADA = "Sua sessão expirou. Entre de novo.";

const respostaSchema = z.object({
  id: z.number().int().positive(),
  resposta: z.enum(RESPOSTAS_COMO_FOI),
});

async function sessao() {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  return user ? { supabase, usuarioId: user.id } : null;
}

/** "Vou ver esse!": guarda a escolha da noite. O título vem do TMDB, não do navegador. */
export async function escolherFilme(tmdbId: unknown): Promise<EstadoComoFoi> {
  const id = tmdbIdSchema.safeParse(tmdbId);
  if (!id.success) return { mensagem: "Filme não encontrado." };

  const atual = await sessao();
  if (!atual) return { mensagem: SESSAO_EXPIRADA };

  const gravado = await gravarEscolha(atual.supabase, id.data);
  if (gravado.ok) return {};
  return {
    mensagem:
      gravado.erro === "filme-nao-encontrado"
        ? "Filme não encontrado."
        : "Não foi possível guardar sua escolha agora. Tente de novo.",
  };
}

/** Chamada uma vez pelo navegador quando o cartão "Como foi?" aparece. */
export async function exibirComoFoi(id: unknown): Promise<void> {
  const valido = z.number().int().positive().safeParse(id);
  if (!valido.success) return;
  const atual = await sessao();
  if (atual) await contarExibicao(atual.supabase, valido.data);
}

/** Resposta do cartão "Como foi?" (um formulário por botão, funciona sem JS). */
export async function responderComoFoi(
  _anterior: EstadoComoFoi,
  formData: FormData,
): Promise<EstadoComoFoi> {
  const erroGenerico = { mensagem: "Não foi possível salvar sua resposta agora. Tente de novo." };
  const valido = respostaSchema.safeParse({
    id: Number(formData.get("id")),
    resposta: formData.get("resposta"),
  });
  if (!valido.success) return erroGenerico;

  const atual = await sessao();
  if (!atual) return { mensagem: SESSAO_EXPIRADA };

  const { id, resposta } = valido.data;
  const gravado = await gravarResposta(atual.supabase, atual.usuarioId, id, resposta);
  if (!gravado.ok) return erroGenerico;

  revalidatePath("/dashboard");
  revalidatePath(`/filme/${gravado.tmdbId}`);
  revalidatePath("/listas");
  return {};
}
import "server-only";

import { devePerguntar, visitaNova } from "@/features/como-foi/regras";
import { definirLista } from "@/features/listas/gravar";
import type { RESPOSTAS_COMO_FOI } from "@/features/metricas/eventos";
import { registrarEvento } from "@/features/metricas/registrar";
import { definirReacao } from "@/features/reacoes/gravar";
import type { ClienteSupabase } from "@/lib/supabase/token";
import { obterFilme } from "@/lib/tmdb/filmes";
import type { FilmeDetalhes } from "@/lib/tmdb/tipos";

export type RespostaComoFoi = (typeof RESPOSTAS_COMO_FOI)[number];

type Erro = "filme-nao-encontrado" | "nao-encontrada" | "tmdb" | "banco";
export type ResultadoComoFoi = { ok: true; tmdbId: number } | { ok: false; erro: Erro };

type BuscarFilme = (id: number) => Promise<FilmeDetalhes | null>;

function falhaNoBanco(acao: string, erro: { code: string; message: string }): ResultadoComoFoi {
  console.error(`[como-foi] falha ao ${acao}:`, erro.code, erro.message);
  return { ok: false, erro: "banco" };
}

/** Guarda o "Vou ver esse!": só o filme e o título do TMDB, nunca as respostas do wizard. */
export async function gravarEscolha(
  supabase: ClienteSupabase,
  tmdbId: number,
  buscarFilme: BuscarFilme = obterFilme,
): Promise<ResultadoComoFoi> {
  let filme: FilmeDetalhes | null;
  try {
    filme = await buscarFilme(tmdbId);
  } catch {
    return { ok: false, erro: "tmdb" };
  }
  if (!filme) return { ok: false, erro: "filme-nao-encontrado" };

  const { error } = await supabase
    .from("escolhas_noite")
    .insert({ tipo: "filme", tmdb_id: tmdbId, titulo: filme.titulo });
  return error ? falhaNoBanco("gravar a escolha", error) : { ok: true, tmdbId };
}

/**
 * Conta a exibição do cartão. Só uma visita nova gasta uma pergunta e gera
 * `como_foi_exibido`; recarregar o dashboard na mesma visita não grava nada.
 */
export async function contarExibicao(
  supabase: ClienteSupabase,
  id: number,
  agora = new Date(),
): Promise<boolean> {
  const { data: escolha, error } = await supabase
    .from("escolhas_noite")
    .select("escolhido_em, perguntado_em, vezes_perguntado, respondido_em")
    .eq("id", id)
    .maybeSingle();
  if (error) {
    falhaNoBanco("ler a escolha", error);
    return false;
  }
  if (!escolha || !devePerguntar(escolha, agora) || !visitaNova(escolha, agora)) return false;

  const { error: erroUpdate } = await supabase
    .from("escolhas_noite")
    .update({ vezes_perguntado: escolha.vezes_perguntado + 1, perguntado_em: agora.toISOString() })
    .eq("id", id)
    // Duas abas ao mesmo tempo não contam duas visitas.
    .eq("vezes_perguntado", escolha.vezes_perguntado);
  if (erroUpdate) {
    falhaNoBanco("contar a exibição", erroUpdate);
    return false;
  }
  await registrarEvento(supabase, { nome: "como_foi_exibido" });
  return true;
}

export const GRAVACOES = { definirReacao, definirLista };

/**
 * Responde "Como foi?". Uma reação grava a reação e "Já assisti" antes de marcar a
 * escolha como respondida, para uma falha deixar a pergunta de pé. "Não cheguei a ver"
 * só marca como respondida. Responder de novo não grava nada.
 */
export async function gravarResposta(
  supabase: ClienteSupabase,
  usuarioId: string,
  id: number,
  resposta: RespostaComoFoi,
  gravacoes = GRAVACOES,
): Promise<ResultadoComoFoi> {
  const { data: escolha, error } = await supabase
    .from("escolhas_noite")
    .select("tmdb_id, respondido_em")
    .eq("id", id)
    .maybeSingle();
  if (error) return falhaNoBanco("ler a escolha", error);
  if (!escolha) return { ok: false, erro: "nao-encontrada" };
  const tmdbId = escolha.tmdb_id;
  if (escolha.respondido_em !== null) return { ok: true, tmdbId };

  if (resposta !== "nao-vi") {
    const reacao = await gravacoes.definirReacao(supabase, usuarioId, tmdbId, resposta);
    if (!reacao.ok) return reacao;
    const lista = await gravacoes.definirLista(supabase, usuarioId, tmdbId, "assistido");
    if (!lista.ok) return lista;
  }

  const { error: erroUpdate } = await supabase
    .from("escolhas_noite")
    .update({ respondido_em: new Date().toISOString() })
    .eq("id", id);
  if (erroUpdate) return falhaNoBanco("marcar a resposta", erroUpdate);

  await registrarEvento(supabase, { nome: "como_foi_respondido", dados: { resposta } });
  return { ok: true, tmdbId };
}
