  tmdbId,
  titulo,
  trocas,
  aoEscolher,
}: {
  tmdbId: number;
  titulo: string;
  trocas: number;
  /** Avisa a tela do wizard, por exemplo para não registrar `wizard_abandonado`. */
  aoEscolher?: () => void;
}) {
