const OPCOES: [Resposta, string, LucideIcon][] = [
  ["amei", ROTULOS_REACAO.amei, Heart],
  ["gostei", ROTULOS_REACAO.gostei, ThumbsUp],
  ["nao-gostei", ROTULOS_REACAO["nao-gostei"], ThumbsDown],
  ["nao-vi", "Não cheguei a ver", EyeOff],
];

/**
